{-# LANGUAGE DataKinds         #-}
{-# LANGUAGE DeriveGeneric     #-}
{-# LANGUAGE DeriveTraversable #-}
{-# LANGUAGE FlexibleContexts  #-}
{-# LANGUAGE FlexibleInstances #-}
{-# LANGUAGE GADTs             #-}
{-# LANGUAGE KindSignatures    #-}
{-# LANGUAGE LambdaCase        #-}
{-# LANGUAGE PatternSynonyms   #-}
{-# LANGUAGE RankNTypes        #-}
{-# LANGUAGE TemplateHaskell   #-}
{-# LANGUAGE TypeFamilies      #-}
{-# OPTIONS_GHC -Wno-missing-signatures -Wno-redundant-constraints -Wno-orphans #-}
-- | Scope-safe syntax of the monolithic language, generated by free-foil's
-- Template Haskell from "Monolith.Raw": the signature @TermSig@, the term
-- type @FFTerm@, the pattern type @FFPattern@ with one constructor for one
-- name and one for two, the pattern synonyms @FFLam@, @FFApp@ and so on, and
-- the conversions @toTerm@ and @fromTerm@.
module Monolith.Generated where

import Control.DeepSeq (NFData (rnf))
import qualified Control.Monad.Foil as Foil
import Control.Monad.Free.Foil (AST)
import Control.Monad.Free.Foil.TH.MkFreeFoil
import Data.Bifunctor.TH
import Data.ZipMatchK
import Data.ZipMatchK.TH (deriveZipMatchK)
import Generics.Kind.TH (deriveGenericK)

import Monolith.Raw
import Monolith.Syntax.Print (printTree)

mkFreeFoil config

deriveGenericK ''FFPattern
instance Foil.SinkableK FFPattern
instance Foil.HasNameBinders FFPattern
instance Foil.UnifiablePattern FFPattern

deriveBifunctor ''TermSig
deriveBifoldable ''TermSig
deriveBitraversable ''TermSig
instance ZipMatchK VarIdent where zipMatchWithK = zipMatchViaEq
deriveZipMatchK ''TermSig

mkFreeFoilConversions config

-- | Terms print through the raw conversion and BNFC's printer. Variables are
-- named by foil identifier, so the output re-parses but is not α-canonical.
instance Show (AST FFPattern TermSig n) where
  show = printTree . fromTerm

-- 'NFData' for the generated types, for tests and benchmarks that force terms.
instance NFData (FFPattern x y) where
  rnf (FFPatternVar x)    = rnf (Foil.nameId (Foil.nameOf x))
  rnf (FFPatternPair x y) = rnf (Foil.nameId (Foil.nameOf x)) `seq` rnf (Foil.nameId (Foil.nameOf y))

instance (NFData scope, NFData term) => NFData (TermSig scope term)
